// ---- Supabase Auth (REST, sans SDK) : appelé en parallèle du système local
// existant pendant la migration. La clé anon est faite pour être publique.
async function supabaseSignUp(email, password) {
  try {
    const res = await fetch(`${SUPABASE_URL_BASE}/auth/v1/signup`, {
      method: "POST",
      headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY },
      body: JSON.stringify({ email, password }),
    });
    const data = await res.json();
    if (!res.ok) return { ok: false, error: data.msg || data.error_description || "Échec de la création du compte sécurisé." };
    return { ok: true, userId: data.id || data.user?.id, accessToken: data.access_token || null };
  } catch {
    return { ok: false, error: "Impossible de contacter le service d'authentification." };
  }
}
async function supabaseSignIn(email, password) {
  try {
    const res = await fetch(`${SUPABASE_URL_BASE}/auth/v1/token?grant_type=password`, {
      method: "POST",
      headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY },
      body: JSON.stringify({ email, password }),
    });
    const data = await res.json();
    if (!res.ok) return { ok: false, error: data.error_description || "Échec de connexion sécurisée." };
    return { ok: true, userId: data.user?.id, accessToken: data.access_token };
  } catch {
    return { ok: false, error: "Impossible de contacter le service d'authentification." };
  }
}
async function supabaseUpsertProfile(accessToken, profile) {
  try {
    await fetch(`${SUPABASE_URL_BASE}/rest/v1/profiles`, {
      method: "POST",
      headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${accessToken}`, Prefer: "resolution=merge-duplicates,return=minimal" },
      body: JSON.stringify(profile),
    });
  } catch {}
}
async function supabaseGetOwnProfile(accessToken) {
  try {
    const res = await fetch(`${SUPABASE_URL_BASE}/rest/v1/profiles?select=*`, {
      headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${accessToken}` },
    });
    const rows = await res.json();
    return Array.isArray(rows) && rows[0] ? rows[0] : null;
  } catch {
    return null;
  }
}


