/* ---- photo (galerie) ---- */
function readFileAsDataURL(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(new Error("Lecture du fichier impossible"));
    reader.readAsDataURL(file);
  });
}

/* ---- graphique des mouvements ---- */
function buildDailyMovements(txs) {
  const map = {};
  txs.forEach((t) => {
    const day = t.date.slice(0, 10);
    if (!map[day]) map[day] = { date: day, ventes: 0, commissions: 0, retraits: 0, parrainage: 0 };
    if (t.type === "sale") map[day].ventes += t.amount;
    else if (t.type === "commission") map[day].commissions += Math.abs(t.amount);
    else if (t.type === "withdrawal") map[day].retraits += Math.abs(t.amount);
    else if (t.type === "withdrawal_reversed") map[day].retraits -= Math.abs(t.amount);
    else if (t.type === "affiliate_percent" || t.type === "affiliate_bonus") map[day].parrainage += t.amount;
  });
  return Object.values(map).sort((a, b) => a.date.localeCompare(b.date));
}
function buildBalanceSeries(txs) {
  const sorted = [...txs].sort((a, b) => new Date(a.date) - new Date(b.date));
  let running = 0;
  const byDay = {};
  sorted.forEach((t) => { running += t.amount; byDay[t.date.slice(0, 10)] = running; });
  return Object.entries(byDay).map(([date, solde]) => ({ date, solde }));
}

/* ---- commissions & portefeuille ---- */
function commissionRateFor(storeId, items, settings) {
  if (settings.sellerCommissions[storeId]) return settings.sellerCommissions[storeId];
  const totalBase = items.reduce((s, i) => s + i.qty * i.price, 0);
  if (totalBase === 0) return settings.globalCommission;
  let percent = 0, fixed = 0;
  items.forEach((i) => {
    const rate = settings.categoryCommissions[i.category] || settings.globalCommission;
    const weight = (i.qty * i.price) / totalBase;
    percent += rate.percent * weight;
    fixed += rate.fixed;
  });
  return { percent, fixed };
}
function ownerTx(walletTransactions, ownerType, ownerId) {
  return walletTransactions.filter((t) => t.ownerType === ownerType && t.ownerId === ownerId);
}
function ownerBalance(walletTransactions, ownerType, ownerId) {
  return ownerTx(walletTransactions, ownerType, ownerId).reduce((s, t) => s + t.amount, 0);
}
function ownerTotals(walletTransactions, ownerType, ownerId) {
  const txs = ownerTx(walletTransactions, ownerType, ownerId);
  const totalRevenue = txs.filter((t) => t.type === "sale").reduce((s, t) => s + t.amount, 0);
  const totalCommission = Math.abs(txs.filter((t) => t.type === "commission").reduce((s, t) => s + t.amount, 0));
  const totalSales = txs.filter((t) => t.type === "sale").length;
  const balance = txs.reduce((s, t) => s + t.amount, 0);
  return { totalRevenue, totalCommission, totalSales, balance };
}
