/* ============================= SMALL UI HELPERS ============================= */
function Field({ label, children }) {
  return (
    <div>
      <label className="text-xs font-semibold opacity-70">{label}</label>
      <div className="mt-1">{children}</div>
    </div>
  );
}
function TextInput(props) {
  return (
    <input
      {...props}
      className={"w-full px-4 py-2.5 rounded-xl text-sm outline-none " + (props.className || "")}
      style={{ border: `1px solid ${T.line}`, background: "#fff", ...(props.style || {}) }}
    />
  );
}
function PrimaryButton({ children, className = "", ...props }) {
  return (
    <button {...props} className={"px-5 py-2.5 rounded-full text-sm font-semibold transition disabled:opacity-50 " + className}
      style={{ background: T.rust, color: "#fff", ...(props.style || {}) }}>
      {children}
    </button>
  );
}
function GhostButton({ children, className = "", ...props }) {
  return (
    <button {...props} className={"px-5 py-2.5 rounded-full text-sm font-semibold transition " + className}
      style={{ border: `1px solid ${T.line}`, ...(props.style || {}) }}>
      {children}
    </button>
  );
}
function PaymentBadge({ method, size = "md" }) {
  const Icon = method.icon;
  const dim = size === "sm" ? 30 : 40;
  return (
    <div className="flex flex-col items-center gap-1.5">
      <div className="rounded-2xl flex items-center justify-center" style={{ width: dim, height: dim, background: `${method.color}1c`, color: method.color }}>
        <Icon size={size === "sm" ? 15 : 18} />
      </div>
      <span className="text-[11px] font-medium text-center opacity-70 leading-tight">{method.label}</span>
    </div>
  );
}
function ImageUpload({ image, onImageChange, emoji = "🛍️", label = "Photo" }) {
  const inputId = useMemo(() => "img-upload-" + Math.random().toString(36).slice(2), []);
  const [error, setError] = useState("");
  const handleFile = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    if (!file.type.startsWith("image/")) { setError("Veuillez choisir une image."); return; }
    try {
      const dataUrl = await readFileAsDataURL(file);
      onImageChange(dataUrl);
      setError("");
    } catch (err) {
      setError("Impossible de charger cette photo.");
    }
  };
  return (
    <div className="flex items-center gap-3">
      <div className="w-16 h-16 rounded-xl overflow-hidden flex items-center justify-center text-3xl shrink-0" style={{ background: `${T.mustard}18`, border: `1px solid ${T.line}` }}>
        {image ? <img src={image} alt={label} className="w-full h-full object-cover" /> : emoji}
      </div>
      <div className="flex flex-col gap-1.5">
        <label htmlFor={inputId} className="text-xs font-semibold px-3 py-2 rounded-full cursor-pointer inline-flex items-center gap-1.5 w-fit" style={{ border: `1px solid ${T.line}`, background: "#fff" }}>
          <ImageIcon size={13} /> Choisir depuis la galerie
        </label>
        <input id={inputId} type="file" accept="image/*" onChange={handleFile} className="hidden" />
        {image && <button onClick={() => onImageChange(null)} className="text-xs opacity-60 hover:opacity-100 text-left">Retirer la photo</button>}
        {error && <p className="text-xs" style={{ color: T.rust }}>{error}</p>}
      </div>
    </div>
  );
}

/* ============================= APP ROOT ============================= */
export default function App() {
  const [loaded, setLoaded] = useState(false);
  const [users, setUsers] = useState([]);
  const [stores, setStores] = useState([]);
  const [products, setProducts] = useState([]);
  const [orders, setOrders] = useState([]);
  const [promoCodes, setPromoCodes] = useState([]);
  const [sessionUserId, setSessionUserId] = useState(null);
  const [platformSettings, setPlatformSettings] = useState({ globalCommission: { percent: 15, fixed: 0 }, categoryCommissions: {}, sellerCommissions: {}, withdrawalMode: "manual", minWithdrawal: 5000, subscriptionPlans: DEFAULT_SUBSCRIPTION_PLANS, freeTrialEnabled: true, freeTrialDays: 7, aiQuotas: DEFAULT_AI_QUOTAS });
  const [walletTransactions, setWalletTransactions] = useState([]);
  const [withdrawals, setWithdrawals] = useState([]);
  const [referrals, setReferrals] = useState([]);
  const [messages, setMessages] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [disputes, setDisputes] = useState([]);

  const [page, setPage] = useState("home");
  const [pendingDashboardTab, setPendingDashboardTab] = useState(null);
  const [shopSearch, setShopSearch] = useState("");
  const [shopCategory, setShopCategory] = useState("Tous");
  const [shopStoreFilter, setShopStoreFilter] = useState("Toutes");
  const [selectedProductId, setSelectedProductId] = useState(null);
  const [cart, setCart] = useState([]); // {productId, qty}
  const [cartOpen, setCartOpen] = useState(false);
  const [authError, setAuthError] = useState("");

  const [checkoutForm, setCheckoutForm] = useState({ name: "", phone: "", address: "", payment: "mtn" });
  const [promoInput, setPromoInput] = useState("");
  const [appliedPromo, setAppliedPromo] = useState(null);
  const [promoError, setPromoError] = useState("");
  const [processing, setProcessing] = useState(false);
  const [paymentError, setPaymentError] = useState("");
  const [awaitingPayment, setAwaitingPayment] = useState(false);
  const [lastGroupId, setLastGroupId] = useState(null);

  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get(STORAGE_KEY, false);
        if (res && res.value) {
          const d = JSON.parse(res.value);
          setUsers(d.users || []); setStores(d.stores || []); setProducts(d.products || []);
          setOrders(d.orders || []); setPromoCodes(d.promoCodes || []); setSessionUserId(d.sessionUserId || null);
          setPlatformSettings(d.platformSettings ? { subscriptionPlans: DEFAULT_SUBSCRIPTION_PLANS, freeTrialEnabled: true, freeTrialDays: 7, aiQuotas: DEFAULT_AI_QUOTAS, ...d.platformSettings } : { globalCommission: { percent: 15, fixed: 0 }, categoryCommissions: {}, sellerCommissions: {}, withdrawalMode: "manual", minWithdrawal: 5000, subscriptionPlans: DEFAULT_SUBSCRIPTION_PLANS, freeTrialEnabled: true, freeTrialDays: 7, aiQuotas: DEFAULT_AI_QUOTAS });
          setWalletTransactions(d.walletTransactions || []); setWithdrawals(d.withdrawals || []); setReferrals(d.referrals || []);
          setMessages(d.messages || []);
          setFavorites(d.favorites || []); setNotifications(d.notifications || []);
          setBookings(d.bookings || []); setDisputes(d.disputes || []);
        } else {
          const seed = seedData();
          setUsers(seed.users); setStores(seed.stores); setProducts(seed.products);
          setOrders(seed.orders); setPromoCodes(seed.promoCodes); setSessionUserId(seed.sessionUserId);
          setPlatformSettings(seed.platformSettings); setWalletTransactions(seed.walletTransactions);
          setWithdrawals(seed.withdrawals); setReferrals(seed.referrals);
          setMessages(seed.messages || []);
          setFavorites([]); setNotifications([]); setBookings([]); setDisputes([]);
          await window.storage.set(STORAGE_KEY, JSON.stringify(seed), false);
        }
      } catch (e) {
        const seed = seedData();
        setUsers(seed.users); setStores(seed.stores); setProducts(seed.products);
        setOrders(seed.orders); setPromoCodes(seed.promoCodes);
        setPlatformSettings(seed.platformSettings); setWalletTransactions(seed.walletTransactions);
        setWithdrawals(seed.withdrawals); setReferrals(seed.referrals);
        setMessages(seed.messages || []);
        setFavorites([]); setNotifications([]); setBookings([]); setDisputes([]);
      } finally {
        setLoaded(true);
      }
    })();
  }, []);

  const persist = useCallback(async (next) => {
    try { await window.storage.set(STORAGE_KEY, JSON.stringify(next), false); }
    catch (e) { console.error("Erreur de sauvegarde", e); }
  }, []);

  const saveAll = (partial) => {
    const next = {
      users: partial.users ?? users, stores: partial.stores ?? stores,
      products: partial.products ?? products, orders: partial.orders ?? orders,
      promoCodes: partial.promoCodes ?? promoCodes, sessionUserId: partial.sessionUserId !== undefined ? partial.sessionUserId : sessionUserId,
      platformSettings: partial.platformSettings ?? platformSettings,
      walletTransactions: partial.walletTransactions ?? walletTransactions,
      withdrawals: partial.withdrawals ?? withdrawals,
      referrals: partial.referrals ?? referrals,
      messages: partial.messages ?? messages,
      favorites: partial.favorites ?? favorites,
      notifications: partial.notifications ?? notifications,
      bookings: partial.bookings ?? bookings,
      disputes: partial.disputes ?? disputes,
    };
    if (partial.users) setUsers(partial.users);
    if (partial.stores) setStores(partial.stores);
    if (partial.products) setProducts(partial.products);
    if (partial.orders) setOrders(partial.orders);
    if (partial.promoCodes) setPromoCodes(partial.promoCodes);
    if (partial.sessionUserId !== undefined) setSessionUserId(partial.sessionUserId);
    if (partial.platformSettings) setPlatformSettings(partial.platformSettings);
    if (partial.walletTransactions) setWalletTransactions(partial.walletTransactions);
    if (partial.withdrawals) setWithdrawals(partial.withdrawals);
    if (partial.referrals) setReferrals(partial.referrals);
    if (partial.messages) setMessages(partial.messages);
    if (partial.favorites) setFavorites(partial.favorites);
    if (partial.notifications) setNotifications(partial.notifications);
    if (partial.bookings) setBookings(partial.bookings);
    if (partial.disputes) setDisputes(partial.disputes);
    persist(next);
  };

  const currentUser = users.find((u) => u.id === sessionUserId) || null;
  const currentStore = currentUser?.storeId ? stores.find((s) => s.id === currentUser.storeId) : null;

  const goTo = (p) => { setPage(p); setAuthError(""); window.scrollTo?.(0, 0); };

  const logout = () => { saveAll({ sessionUserId: null }); goTo("home"); };

  const login = async (email, password) => {
    const u = users.find((x) => x.email.toLowerCase() === email.trim().toLowerCase() && x.password === password);
    if (u) {
      if (!u.active) { setAuthError("Ce compte a été suspendu. Contactez l'administration."); return; }
      setPendingDashboardTab(null);
      // Connexion Supabase Auth réelle en parallèle (transition) : si le compte a
      // déjà été migré, on récupère un jeton valide pour sécuriser ses actions.
      let patch = { sessionUserId: u.id };
      const authRes = await supabaseSignIn(email, password);
      if (authRes.ok) patch = { ...patch, users: users.map((x) => (x.id === u.id ? { ...x, supabaseAccessToken: authRes.accessToken, supabaseUserId: authRes.userId } : x)) };
      saveAll(patch);
      if (u.role === "admin") goTo("adminDashboard");
      else if (u.role === "seller") goTo("sellerDashboard");
      else goTo("buyerDashboard");
      return;
    }

    // Aucun compte local : ce peut être un compte créé directement côté
    // Supabase (ex. un vrai administrateur). On tente une connexion réelle.
    const authRes = await supabaseSignIn(email.trim(), password);
    if (!authRes.ok) { setAuthError("Adresse e-mail ou mot de passe incorrect."); return; }
    const profile = await supabaseGetOwnProfile(authRes.accessToken);
    if (!profile) { setAuthError("Compte authentifié mais aucun profil trouvé."); return; }
    const localId = "u_sb_" + profile.id;
    const shadowUser = {
      id: localId, name: profile.name || email, email: email.trim(), phone: profile.phone || "",
      password, role: profile.role === "admin" ? "admin" : profile.role === "vendeur" || profile.role === "les_deux" ? "seller" : "buyer",
      country: profile.country || "Sénégal", active: true, referralCode: (profile.name || "USR").replace(/\s+/g, "").slice(0, 5).toUpperCase() + Math.random().toString(36).slice(2, 5).toUpperCase(),
      referredBy: null, supabaseAccessToken: authRes.accessToken, supabaseUserId: profile.id, ...(profile.store_id ? { storeId: profile.store_id } : {}),
    };
    setPendingDashboardTab(null);
    saveAll({ users: [...users, shadowUser], sessionUserId: localId });
    if (shadowUser.role === "admin") goTo("adminDashboard");
    else if (shadowUser.role === "seller") goTo("sellerDashboard");
    else goTo("buyerDashboard");
  };

  const register = async (form) => {
    const fullName = `${form.firstName || ""} ${form.lastName || ""}`.trim() || form.name || "";
    if (!fullName || !form.email.trim() || !form.password) { setAuthError("Merci de remplir tous les champs obligatoires."); return; }
    if (form.password !== form.passwordConfirm) { setAuthError("Les mots de passe ne correspondent pas."); return; }
    if (!form.acceptedTerms) { setAuthError("Merci d'accepter les conditions d'utilisation."); return; }
    if (users.some((u) => u.email.toLowerCase() === form.email.trim().toLowerCase())) { setAuthError("Un compte existe déjà avec cet e-mail."); return; }
    const userId = "u_" + Date.now();
    const isSeller = form.accountType === "vendeur" || form.accountType === "both";
    const role = isSeller ? "seller" : "buyer";
    let newStores = stores;
    let storeId = undefined;
    if (isSeller) {
      storeId = "s_" + Date.now();
      newStores = [...stores, { id: storeId, ownerId: userId, name: form.storeName || fullName + " Shop", tagline: form.storeTagline || "Nouvelle boutique sur PJD Maker", mainCategory: form.storeCategory || CATEGORIES[0], deliveryFee: 1500, emoji: "🛍️", active: true }];
    }
    const referralCode = (fullName.replace(/\s+/g, "").slice(0, 5) + Math.random().toString(36).slice(2, 5)).toUpperCase();
    const referrer = form.refCode ? users.find((u) => u.referralCode.toLowerCase() === form.refCode.trim().toLowerCase()) : null;
    const countryInfo = findCountry(form.country);

    // Création du vrai compte Supabase Auth en parallèle (37.4) : le rôle
    // stocké côté serveur reste 'client' par défaut (le trigger empêche toute
    // élévation), le profil local garde la richesse actuelle (accountType, boutique…).
    const authRes = await supabaseSignUp(form.email.trim(), form.password);
    let supabaseAccessToken = null, supabaseUserId = null;
    if (authRes.ok) {
      supabaseAccessToken = authRes.accessToken; supabaseUserId = authRes.userId;
      if (supabaseAccessToken && supabaseUserId) {
        await supabaseUpsertProfile(supabaseAccessToken, { id: supabaseUserId, name: fullName, phone: form.phone.trim(), country: form.country || "Sénégal", store_id: storeId || null });
      }
    }

    const newUser = {
      id: userId, name: fullName, firstName: form.firstName, lastName: form.lastName, username: form.username,
      email: form.email.trim(), phone: form.phone.trim(), password: form.password, role, accountType: form.accountType,
      country: form.country || "Sénégal", currency: countryInfo.currency, language: countryInfo.language, timezone: countryInfo.timezone,
      active: true, referralCode, referredBy: referrer ? referrer.id : null, supabaseAccessToken, supabaseUserId, ...(storeId ? { storeId } : {}),
    };
    const newReferrals = referrer ? [...referrals, { id: "ref_" + Date.now(), referrerId: referrer.id, refereeId: userId, rewarded: false }] : referrals;
    saveAll({ users: [...users, newUser], stores: newStores, sessionUserId: userId, referrals: newReferrals });
    setPendingDashboardTab(null);
    goTo(role === "seller" ? "sellerDashboard" : "buyerDashboard");
  };

  const becomeSeller = (storeName, storeTagline) => {
    if (!currentUser) return;
    const storeId = "s_" + Date.now();
    const newStores = [...stores, { id: storeId, ownerId: currentUser.id, name: storeName, tagline: storeTagline || "Nouvelle boutique sur PJD Maker", deliveryFee: 1500, emoji: "🛍️", active: true }];
    const newUsers = users.map((u) => (u.id === currentUser.id ? { ...u, role: "seller", storeId } : u));
    saveAll({ users: newUsers, stores: newStores });
    goTo("sellerDashboard");
  };

  const handleCreerBoutique = () => {
    setPendingDashboardTab(null);
    if (!currentUser) { goTo("registerSeller"); return; }
    if (currentUser.role === "seller") { goTo("sellerDashboard"); return; }
    if (currentUser.role === "buyer") { goTo("becomeSeller"); return; }
    goTo("adminDashboard");
  };

  const goToAccountSection = (target) => {
    if (!currentUser) { goTo("login"); return; }
    if (target.page === "favoris" || target.page === "profile" || target.page === "contact" || target.page === "cgu" || target.page === "privacy") {
      goTo(target.page);
      return;
    }
    setPendingDashboardTab(target.tab || "overview");
    goTo(target.dashboard === "seller" ? "sellerDashboard" : target.dashboard === "admin" ? "adminDashboard" : "buyerDashboard");
  };

  // ---- catalogue actif (boutiques actives uniquement) ----
  const activeStoreIds = new Set(stores.filter((s) => s.active).map((s) => s.id));
  const liveProducts = products.filter((p) => activeStoreIds.has(p.storeId));

  const filteredShopProducts = liveProducts.filter((p) => {
    const store = stores.find((s) => s.id === p.storeId);
    const matchCat = shopCategory === "Tous" || p.category === shopCategory;
    const matchStore = shopStoreFilter === "Toutes" || p.storeId === shopStoreFilter;
    const matchSearch = p.name.toLowerCase().includes(shopSearch.toLowerCase());
    return matchCat && matchStore && matchSearch;
  });

  const popularProducts = liveProducts.filter((p) => p.popular);
  const bestSellers = [...liveProducts].sort((a, b) => b.sold - a.sold).slice(0, 4);

  const cartItems = cart.map((c) => ({ ...c, product: products.find((p) => p.id === c.productId) })).filter((c) => c.product);
  const cartCount = cartItems.reduce((s, c) => s + c.qty, 0);
  const cartSubtotal = cartItems.reduce((s, c) => s + c.qty * c.product.price, 0);
  const eligibleSubtotal = appliedPromo ? cartItems.filter((c) => c.product.storeId === appliedPromo.storeId).reduce((s, c) => s + c.qty * c.product.price, 0) : 0;
  const discount = appliedPromo ? (appliedPromo.type === "percent" ? Math.round((eligibleSubtotal * appliedPromo.value) / 100) : Math.min(appliedPromo.value, eligibleSubtotal)) : 0;
  const storeIdsInCart = [...new Set(cartItems.map((c) => c.product.storeId))];
  const deliveryFee = storeIdsInCart.reduce((s, id) => s + (stores.find((st) => st.id === id)?.deliveryFee || 0), 0);
  const cartTotal = Math.max(0, cartSubtotal - discount) + deliveryFee;

  const selectedProduct = products.find((p) => p.id === selectedProductId);
  const selectedProductStore = selectedProduct ? stores.find((s) => s.id === selectedProduct.storeId) : null;

  const addToCart = (productId, qty = 1) => {
    setCart((prev) => {
      const existing = prev.find((c) => c.productId === productId);
      if (existing) return prev.map((c) => (c.productId === productId ? { ...c, qty: c.qty + qty } : c));
      return [...prev, { productId, qty }];
    });
    setCartOpen(true);
  };
  const changeQty = (productId, delta) => setCart((prev) => prev.map((c) => (c.productId === productId ? { ...c, qty: c.qty + delta } : c)).filter((c) => c.qty > 0));
  const removeFromCart = (productId) => setCart((prev) => prev.filter((c) => c.productId !== productId));

  const applyPromo = () => {
    const match = promoCodes.find((p) => p.active && p.code.toLowerCase() === promoInput.trim().toLowerCase());
    if (!match) { setAppliedPromo(null); setPromoError("Code promo invalide ou expiré."); return; }
    const hasEligible = cartItems.some((c) => c.product.storeId === match.storeId);
    if (!hasEligible) {
      const storeName = stores.find((s) => s.id === match.storeId)?.name || "cette boutique";
      setAppliedPromo(null); setPromoError(`Ce code n'est valable que pour la boutique ${storeName}.`); return;
    }
    setAppliedPromo(match); setPromoError("");
  };
  const removePromo = () => { setAppliedPromo(null); setPromoInput(""); setPromoError(""); };

  const finalizeOrder = (groupId, paymentStatus) => {
    const nowIso = new Date().toISOString();
    const newOrders = storeIdsInCart.map((storeId) => {
      const itemsForStore = cartItems.filter((c) => c.product.storeId === storeId);
      const subtotal = itemsForStore.reduce((s, c) => s + c.qty * c.product.price, 0);
      const storeDiscount = appliedPromo && appliedPromo.storeId === storeId ? discount : 0;
      const storeDeliveryFee = stores.find((s) => s.id === storeId)?.deliveryFee || 0;
      const items = itemsForStore.map((c) => ({ productId: c.product.id, name: c.product.name, qty: c.qty, price: c.product.price, category: c.product.category }));
      const commissionBase = Math.max(0, subtotal - storeDiscount);
      const rate = commissionRateFor(storeId, items, platformSettings);
      const commissionAmount = Math.min(commissionBase, Math.round((commissionBase * rate.percent) / 100 + rate.fixed));
      const total = subtotal - storeDiscount + storeDeliveryFee;
      const netToSeller = commissionBase - commissionAmount + storeDeliveryFee;
      return {
        id: groupId + "-" + storeId.toUpperCase(), groupId, storeId,
        buyerId: currentUser?.id || null,
        items, subtotal, discount: storeDiscount, promoCode: storeDiscount > 0 ? appliedPromo.code : null,
        deliveryFee: storeDeliveryFee, total,
        commissionRate: Math.round(rate.percent * 10) / 10, commissionAmount, netToSeller,
        customer: { name: checkoutForm.name, phone: checkoutForm.phone, address: checkoutForm.address },
        payment: checkoutForm.payment, date: nowIso, status: paymentStatus || "En attente", trackingNumber: "", carrier: "", returnStatus: "aucun",
      };
    });

    const nextProducts = products.map((p) => {
      const inCart = cart.find((c) => c.productId === p.id);
      return inCart ? { ...p, stock: Math.max(0, p.stock - inCart.qty), sold: p.sold + inCart.qty } : p;
    });

    // Alimentation du portefeuille de chaque boutique
    let newWalletTx = [...walletTransactions];
    newOrders.forEach((o) => {
      newWalletTx.push({ id: "t" + Date.now() + o.storeId, ownerType: "store", ownerId: o.storeId, type: "sale", amount: o.subtotal - o.discount, date: nowIso, note: o.id });
      if (o.commissionAmount > 0) {
        newWalletTx.push({ id: "t" + Date.now() + o.storeId + "c", ownerType: "store", ownerId: o.storeId, type: "commission", amount: -o.commissionAmount, date: nowIso, note: o.id });
      }
    });

    // Récompenses de parrainage : premier achat de l'acheteur filleul
    let newReferrals = referrals;
    const groupTotal = newOrders.reduce((s, o) => s + o.total, 0);
    if (currentUser) {
      const buyerReferral = referrals.find((r) => r.refereeId === currentUser.id && !r.rewarded);
      const isFirstPurchase = !orders.some((o) => o.buyerId === currentUser.id);
      if (buyerReferral && isFirstPurchase) {
        const bonusPercent = Math.round(groupTotal * 0.05);
        newWalletTx.push({ id: "aff" + Date.now() + "p", ownerType: "user", ownerId: buyerReferral.referrerId, type: "affiliate_percent", amount: bonusPercent, date: nowIso, note: `Parrainage : 1er achat de ${currentUser.name}` });
        newWalletTx.push({ id: "aff" + Date.now() + "f", ownerType: "user", ownerId: buyerReferral.referrerId, type: "affiliate_bonus", amount: 1000, date: nowIso, note: `Bonus parrainage : 1er achat de ${currentUser.name}` });
        newReferrals = referrals.map((r) => (r.id === buyerReferral.id ? { ...r, rewarded: true } : r));
      }
    }
    // Récompenses de parrainage : première vente d'une boutique filleule
    newOrders.forEach((o) => {
      const storeOwner = users.find((u) => u.storeId === o.storeId);
      if (!storeOwner) return;
      const sellerReferral = newReferrals.find((r) => r.refereeId === storeOwner.id && !r.rewarded);
      const isFirstSaleForStore = !orders.some((ord) => ord.storeId === o.storeId);
      if (sellerReferral && isFirstSaleForStore) {
        const bonusPercent = Math.round(o.total * 0.05);
        newWalletTx.push({ id: "aff" + Date.now() + o.storeId + "p", ownerType: "user", ownerId: sellerReferral.referrerId, type: "affiliate_percent", amount: bonusPercent, date: nowIso, note: `Parrainage : 1ère vente de ${storeOwner.name}` });
        newWalletTx.push({ id: "aff" + Date.now() + o.storeId + "f", ownerType: "user", ownerId: sellerReferral.referrerId, type: "affiliate_bonus", amount: 1000, date: nowIso, note: `Bonus parrainage : 1ère vente de ${storeOwner.name}` });
        newReferrals = newReferrals.map((r) => (r.id === sellerReferral.id ? { ...r, rewarded: true } : r));
      }
    });

    saveAll({ orders: [...orders, ...newOrders], products: nextProducts, walletTransactions: newWalletTx, referrals: newReferrals });
    newOrders.forEach((o) => pushNotification({ type: "order", target: "store", storeId: o.storeId, text: `Nouvelle commande ${o.id} (${money(o.total)})` }));
    setCart([]); removePromo(); setLastGroupId(groupId); setProcessing(false); setAwaitingPayment(false); goTo("orderConfirmation");
  };

  const pollStripePayment = (orderId, groupId) => {
    let attempts = 0;
    const maxAttempts = 60; // ~5 minutes at 5s intervals
    const interval = setInterval(async () => {
      attempts++;
      try {
        const res = await fetch(`${SUPABASE_FUNCTIONS_URL}/order-status`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ orderId }),
        });
        const data = await res.json();
        if (data.status === "paid") {
          clearInterval(interval);
          setPaymentError("");
          finalizeOrder(groupId, "Confirmée");
        } else if (data.status === "expired" || attempts >= maxAttempts) {
          clearInterval(interval);
          setAwaitingPayment(false);
          setPaymentError(attempts >= maxAttempts ? "Le paiement n'a pas été confirmé à temps. Vérifiez votre onglet Stripe ou réessayez." : "Le lien de paiement Stripe a expiré. Réessayez.");
        }
      } catch {
        if (attempts >= maxAttempts) { clearInterval(interval); setAwaitingPayment(false); }
      }
    }, 5000);
  };

  const placeOrder = async () => {
    if (!checkoutForm.name.trim() || !checkoutForm.phone.trim() || !checkoutForm.address.trim() || cartItems.length === 0) return;
    setPaymentError("");
    setProcessing(true);

    const groupId = "CMD-" + Math.random().toString(36).slice(2, 7).toUpperCase();

    if (checkoutForm.payment === "stripe") {
      try {
        const res = await fetch(`${SUPABASE_FUNCTIONS_URL}/stripe-checkout`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            items: cartItems.map((c) => ({ name: c.product.name, qty: c.qty, price: c.product.price })),
            currency: "xof",
            orderId: groupId,
            customerEmail: currentUser?.email,
            successUrl: window.location.href,
            cancelUrl: window.location.href,
          }),
        });
        const data = await res.json();
        if (!res.ok || data.error) {
          setPaymentError(data.error || "Le paiement Stripe a échoué. Réessayez ou choisissez un autre moyen de paiement.");
          setProcessing(false);
          return;
        }
        window.open(data.url, "_blank");
        setPaymentError("Un onglet Stripe s'est ouvert pour finaliser le paiement par carte. Votre commande se confirmera automatiquement ici dès que le paiement sera reçu…");
        setProcessing(false);
        setAwaitingPayment(true);
        pollStripePayment(groupId, groupId);
        return;
      } catch (err) {
        setPaymentError("Impossible de contacter Stripe pour le moment. Réessayez ou choisissez un autre moyen de paiement.");
        setProcessing(false);
        return;
      }
    }

    await new Promise((r) => setTimeout(r, 1400));
    finalizeOrder(groupId, "En attente");
  };

  const requestWithdrawal = async (ownerType, ownerId, amount, method) => {
    const bal = ownerBalance(walletTransactions, ownerType, ownerId);
    if (amount < platformSettings.minWithdrawal) return { ok: false, error: `Le retrait minimum est de ${money(platformSettings.minWithdrawal)}.` };
    if (amount > bal) return { ok: false, error: "Solde insuffisant pour ce retrait." };

    // Validation serveur (Module 37) : le montant, le solde et les limites sont
    // recalculés côté serveur à partir du grand livre Supabase avant toute acceptation.
    // Seules les boutiques (ownerType "store") sont aujourd'hui suivies dans ce grand livre.
    let serverWithdrawalId = null;
    if (ownerType === "store") {
      try {
        const res = await fetch(`${SUPABASE_FUNCTIONS_URL}/wallet-ledger`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            ...(currentUser?.supabaseAccessToken ? { Authorization: `Bearer ${currentUser.supabaseAccessToken}` } : {}),
          },
          body: JSON.stringify({ action: "request-withdrawal", storeId: ownerId, amount, method }),
        });
        const data = await res.json();
        if (!res.ok || data.error) return { ok: false, error: data.error || "Le serveur a refusé cette demande de retrait." };
        serverWithdrawalId = data.withdrawal?.id || null;
      } catch {
        return { ok: false, error: "Impossible de valider ce retrait côté serveur pour le moment. Réessayez." };
      }
    }

    const id = "w" + Date.now();
    const status = platformSettings.withdrawalMode === "auto" ? "approved" : "pending";
    const nowIso = new Date().toISOString();
    const newWithdrawals = [...withdrawals, { id, ownerType, ownerId, amount, method, status, date: nowIso, serverWithdrawalId }];
    const newTx = [...walletTransactions, { id: "t" + Date.now(), ownerType, ownerId, type: "withdrawal", amount: -amount, date: nowIso, note: id }];
    saveAll({ withdrawals: newWithdrawals, walletTransactions: newTx });
    if (status === "pending") pushNotification({ type: "withdrawal", target: "admin", text: `Demande de retrait de ${money(amount)} en attente` });
    return { ok: true };
  };
  const decideWithdrawalOnServer = async (withdrawalId, decision) => {
    if (!withdrawalId) return { ok: true, skipped: true }; // retrait legacy sans équivalent serveur
    if (!currentUser?.supabaseAccessToken) return { ok: false, error: "Connectez-vous avec le vrai compte administrateur pour valider ce retrait." };
    try {
      const res = await fetch(`${SUPABASE_FUNCTIONS_URL}/wallet-ledger`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${currentUser.supabaseAccessToken}` },
        body: JSON.stringify({ action: "decide-withdrawal", withdrawalId, decision }),
      });
      const data = await res.json();
      if (!res.ok || data.error) return { ok: false, error: data.error || "Le serveur a refusé cette action." };
      return { ok: true };
    } catch {
      return { ok: false, error: "Impossible de contacter le serveur pour valider ce retrait." };
    }
  };

  const approveWithdrawal = async (id) => {
    const w = withdrawals.find((x) => x.id === id);
    const res = await decideWithdrawalOnServer(w?.serverWithdrawalId, "approved");
    if (!res.ok) { pushNotification({ type: "withdrawal", target: "admin", text: `Échec de l'approbation : ${res.error}` }); return res; }
    saveAll({ withdrawals: withdrawals.map((x) => (x.id === id ? { ...x, status: "approved" } : x)) });
    return { ok: true };
  };
  const rejectWithdrawal = async (id) => {
    const w = withdrawals.find((x) => x.id === id);
    if (!w) return { ok: false, error: "Retrait introuvable." };
    const res = await decideWithdrawalOnServer(w.serverWithdrawalId, "rejected");
    if (!res.ok) { pushNotification({ type: "withdrawal", target: "admin", text: `Échec du refus : ${res.error}` }); return res; }
    const newTx = [...walletTransactions, { id: "t" + Date.now(), ownerType: w.ownerType, ownerId: w.ownerId, type: "withdrawal_reversed", amount: w.amount, date: new Date().toISOString(), note: "Retrait refusé : " + id }];
    saveAll({ withdrawals: withdrawals.map((x) => (x.id === id ? { ...x, status: "rejected" } : x)), walletTransactions: newTx });
    return { ok: true };
  };

  // ---- commandes : statut, transporteur, suivi, retours ----
  const updateOrder = (orderId, patch) => saveAll({ orders: orders.map((o) => (o.id === orderId ? { ...o, ...patch } : o)) });

  // ---- fiches produit : vues (statistiques) ----
  const trackProductView = (productId) => saveAll({ products: products.map((p) => (p.id === productId ? { ...p, views: (p.views || 0) + 1 } : p)) });

  // ---- avis clients ----
  const addReview = (productId, review) => {
    const next = products.map((p) => (p.id === productId ? { ...p, reviews: [...(p.reviews || []), review] } : p));
    saveAll({ products: next });
  };

  // ---- messagerie boutique <-> client / administration ----
  const sendMessage = (msg) => saveAll({ messages: [...messages, { id: "msg" + Date.now() + Math.random().toString(36).slice(2, 6), date: new Date().toISOString(), ...msg }] });

  // ---- publicité : mise en avant produit / boutique ----
  const boostProduct = (productId, storeId, days, cost) => {
    const bal = ownerBalance(walletTransactions, "store", storeId);
    if (cost > bal) return { ok: false, error: "Solde insuffisant pour cette campagne." };
    const until = new Date(Date.now() + days * 86400000).toISOString();
    const nextProducts = products.map((p) => (p.id === productId ? { ...p, sponsoredUntil: until } : p));
    const newTx = [...walletTransactions, { id: "ad" + Date.now(), ownerType: "store", ownerId: storeId, type: "ad_spend", amount: -cost, date: new Date().toISOString(), note: "Mise en avant produit (" + days + " j)" }];
    saveAll({ products: nextProducts, walletTransactions: newTx });
    return { ok: true };
  };
  const boostStore = (storeId, days, cost) => {
    const bal = ownerBalance(walletTransactions, "store", storeId);
    if (cost > bal) return { ok: false, error: "Solde insuffisant pour cette campagne." };
    const until = new Date(Date.now() + days * 86400000).toISOString();
    const nextStores = stores.map((s) => (s.id === storeId ? { ...s, boostedUntil: until } : s));
    const newTx = [...walletTransactions, { id: "ad" + Date.now(), ownerType: "store", ownerId: storeId, type: "ad_spend", amount: -cost, date: new Date().toISOString(), note: "Boost de boutique (" + days + " j)" }];
    saveAll({ stores: nextStores, walletTransactions: newTx });
    return { ok: true };
  };

  // ---- documents & vérification (KYC) ----
  const submitKyc = (storeId, documents) => { saveAll({ stores: stores.map((s) => (s.id === storeId ? { ...s, documents, kycStatus: "en_attente" } : s)) }); pushNotification({ type: "kyc", target: "admin", text: `Documents KYC soumis pour la boutique ${stores.find((s) => s.id === storeId)?.name || storeId}` }); };
  const reviewKyc = (storeId, approved) => saveAll({ stores: stores.map((s) => (s.id === storeId ? { ...s, kycStatus: approved ? "valide" : "refuse", verified: approved ? true : s.verified } : s)) });

  // ---- paramètres du compte ----
  const changePassword = (userId, currentPassword, newPassword) => {
    const u = users.find((x) => x.id === userId);
    if (!u || u.password !== currentPassword) return { ok: false, error: "Mot de passe actuel incorrect." };
    saveAll({ users: users.map((x) => (x.id === userId ? { ...x, password: newPassword } : x)) });
    return { ok: true };
  };
  const updateAccountSettings = (userId, patch) => saveAll({ users: users.map((u) => (u.id === userId ? { ...u, ...patch } : u)) });

  // ---- notifications ----
  const pushNotification = (notif) => {
    const entry = { id: "notif" + Date.now() + Math.random().toString(36).slice(2, 6), date: new Date().toISOString(), read: false, ...notif };
    saveAll({ notifications: [...notifications, entry] });
  };
  const markNotificationRead = (id) => saveAll({ notifications: notifications.map((n) => (n.id === id ? { ...n, read: true } : n)) });

  // ---- favoris (wishlist) ----
  const toggleFavorite = (productId) => {
    if (!currentUser) { goTo("login"); return; }
    const exists = favorites.find((f) => f.userId === currentUser.id && f.productId === productId);
    if (exists) saveAll({ favorites: favorites.filter((f) => f.id !== exists.id) });
    else saveAll({ favorites: [...favorites, { id: "fav" + Date.now() + Math.random().toString(36).slice(2, 5), userId: currentUser.id, productId, date: new Date().toISOString() }] });
  };
  const isFavorite = (productId) => !!currentUser && favorites.some((f) => f.userId === currentUser.id && f.productId === productId);

  // ---- réservation de services / techniciens ----
  const createBooking = (booking) => {
    const entry = { id: "bk" + Date.now(), status: "En attente", date: new Date().toISOString(), ...booking };
    saveAll({ bookings: [...bookings, entry] });
    pushNotification({ type: "booking", target: "store", storeId: booking.storeId, text: `Nouvelle réservation pour "${booking.serviceName}"` });
    return entry;
  };
  const updateBooking = (id, patch) => saveAll({ bookings: bookings.map((b) => (b.id === id ? { ...b, ...patch } : b)) });

  // ---- litiges ----
  const openDispute = (dispute) => {
    const entry = { id: "disp" + Date.now(), status: "Ouvert", date: new Date().toISOString(), messages: [], ...dispute };
    saveAll({ disputes: [...disputes, entry] });
    pushNotification({ type: "dispute", target: "admin", text: `Nouveau litige sur la commande ${dispute.orderId}` });
  };
  const resolveDispute = (id, status, refund) => {
    const d = disputes.find((x) => x.id === id);
    if (!d) return;
    let newTx = walletTransactions;
    if (refund && d.storeId) {
      newTx = [...walletTransactions, { id: "rf" + Date.now(), ownerType: "store", ownerId: d.storeId, type: "commission", amount: -Math.abs(refund), date: new Date().toISOString(), note: "Remboursement litige " + d.orderId }];
    }
    saveAll({ disputes: disputes.map((x) => (x.id === id ? { ...x, status } : x)), walletTransactions: newTx });
  };

  // ---- abonnements vendeur (Standard / Gold / Platinum / Diamond) ----
  const changeSubscriptionPlan = (storeId, planId, cycle) => {
    const plans = platformSettings.subscriptionPlans || DEFAULT_SUBSCRIPTION_PLANS;
    const plan = plans[planId];
    if (!plan) return { ok: false, error: "Formule introuvable." };
    const cost = cycle === "annual" ? plan.annual : plan.monthly;
    if (planId !== "standard" || cost > 0) {
      const bal = ownerBalance(walletTransactions, "store", storeId);
      if (bal < cost) return { ok: false, error: `Solde insuffisant. La formule ${plan.label} (${cycle === "annual" ? "annuelle" : "mensuelle"}) coûte ${money(cost)}.` };
    }
    const days = cycle === "annual" ? 365 : 30;
    const until = new Date(Date.now() + days * 86400000).toISOString();
    const newTx = cost > 0 ? [...walletTransactions, { id: "sub" + Date.now(), ownerType: "store", ownerId: storeId, type: "commission", amount: -cost, date: new Date().toISOString(), note: `Abonnement ${plan.label} (${cycle === "annual" ? "annuel" : "mensuel"})` }] : walletTransactions;
    saveAll({ stores: stores.map((s) => (s.id === storeId ? { ...s, plan: planId, planUntil: until, billingCycle: cycle, trialActive: false } : s)), walletTransactions: newTx });
    pushNotification({ type: "subscription", target: "store", storeId, text: `Abonnement ${plan.label} activé jusqu'au ${new Date(until).toLocaleDateString("fr-FR")}` });
    return { ok: true };
  };
  const startFreeTrial = (storeId) => {
    if (!platformSettings.freeTrialEnabled) return { ok: false, error: "L'essai gratuit n'est pas disponible pour le moment." };
    const store = stores.find((s) => s.id === storeId);
    if (store?.trialUsed) return { ok: false, error: "Vous avez déjà utilisé votre essai gratuit." };
    const days = platformSettings.freeTrialDays || 7;
    const until = new Date(Date.now() + days * 86400000).toISOString();
    saveAll({ stores: stores.map((s) => (s.id === storeId ? { ...s, plan: "gold", planUntil: until, trialActive: true, trialUsed: true, trialStarted: new Date().toISOString() } : s)) });
    pushNotification({ type: "subscription", target: "store", storeId, text: `Essai gratuit Gold activé pour ${days} jours` });
    return { ok: true };
  };
  const adminGrantSubscription = (storeId, planId, days) => {
    const until = new Date(Date.now() + days * 86400000).toISOString();
    saveAll({ stores: stores.map((s) => (s.id === storeId ? { ...s, plan: planId, planUntil: until, trialActive: false } : s)) });
  };
  const adminSuspendSubscription = (storeId) => {
    saveAll({ stores: stores.map((s) => (s.id === storeId ? { ...s, plan: "standard", planUntil: null, trialActive: false } : s)) });
  };
  const updateSubscriptionSettings = (patch) => saveAll({ platformSettings: { ...platformSettings, ...patch } });

  // ---- PJD AI : quotas ----
  const currentMonthKey = () => new Date().toISOString().slice(0, 7);
  const getAiUsage = (store) => {
    const usage = store?.aiUsage;
    if (!usage || usage.month !== currentMonthKey()) return { count: 0, month: currentMonthKey() };
    return usage;
  };
  const getAiQuota = (store) => {
    const quotas = platformSettings.aiQuotas || DEFAULT_AI_QUOTAS;
    const planId = store?.plan && new Date(store?.planUntil || 0) > new Date() ? store.plan : "standard";
    return quotas[planId] ?? quotas.standard;
  };
  const consumeAiUsage = (storeId) => {
    const store = stores.find((s) => s.id === storeId);
    const usage = getAiUsage(store);
    saveAll({ stores: stores.map((s) => (s.id === storeId ? { ...s, aiUsage: { count: usage.count + 1, month: usage.month } } : s)) });
  };

  // ---- PJD AI : appel réel à l'API Claude (Anthropic), sans clé côté client ----
  const callPjdAI = async (storeId, systemPrompt, userMessage) => {
    const store = stores.find((s) => s.id === storeId);
    const usage = getAiUsage(store);
    const quota = getAiQuota(store);
    if (usage.count >= quota) {
      return { ok: false, error: `Quota IA mensuel atteint (${quota} générations). Passez à une formule supérieure pour en obtenir davantage.` };
    }
    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 1000,
          system: systemPrompt,
          messages: [{ role: "user", content: userMessage }],
        }),
      });
      const data = await response.json();
      const text = (data.content || []).filter((b) => b.type === "text").map((b) => b.text).join("\n").trim();
      if (!text) return { ok: false, error: "L'assistant PJD n'a pas pu répondre. Réessayez." };
      consumeAiUsage(storeId);
      return { ok: true, text };
    } catch (err) {
      return { ok: false, error: "Impossible de contacter l'assistant PJD pour le moment." };
    }
  };


  if (!loaded) {
    return <div className="min-h-screen flex items-center justify-center" style={{ background: T.cream }}><Loader2 className="animate-spin" size={28} style={{ color: T.rust }} /></div>;
  }

  const dashboardPages = ["sellerDashboard", "buyerDashboard", "adminDashboard"];
  const isDashboard = dashboardPages.includes(page);

  return (
    <div className="min-h-screen" style={{ background: T.cream, color: T.ink, fontFamily: "'Inter', sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@500;700&display=swap');
        .font-display { font-family: 'Fraunces', serif; }
        .font-mono { font-family: 'JetBrains Mono', monospace; }
        @media print {
          body * { visibility: hidden; }
          .print-area, .print-area * { visibility: visible; }
          .print-area { position: fixed; inset: 0; margin: auto; max-height: none !important; }
          .no-print { display: none !important; }
        }
      `}</style>

      {!isDashboard && (
        <Header
          currentUser={currentUser}
          cartCount={cartCount}
          favoritesCount={currentUser ? favorites.filter((f) => f.userId === currentUser.id).length : 0}
          onCartClick={() => setCartOpen(true)}
          goTo={goTo}
          onCreerBoutique={handleCreerBoutique}
          onLogout={logout}
        />
      )}

      {page === "home" && (
        <HomePage
          stores={stores} popularProducts={popularProducts} bestSellers={bestSellers}
          totalOrders={orders.length} goTo={goTo} onSelectProduct={(id) => { setSelectedProductId(id); goTo("product"); }}
          onSearch={(q) => { setShopSearch(q); goTo("shop"); }} onCreerBoutique={handleCreerBoutique} currentUser={currentUser}
        />
      )}

      {page === "shop" && (
        <ShopPage
          products={filteredShopProducts} stores={stores.filter((s) => s.active)}
          search={shopSearch} setSearch={setShopSearch}
          category={shopCategory} setCategory={setShopCategory}
          storeFilter={shopStoreFilter} setStoreFilter={setShopStoreFilter}
          onSelect={(id) => { setSelectedProductId(id); goTo("product"); }} addToCart={addToCart}
          favorites={favorites} toggleFavorite={toggleFavorite} currentUser={currentUser}
        />
      )}

      {page === "product" && selectedProduct && (
        <ProductPage product={selectedProduct} store={selectedProductStore} onBack={() => goTo("shop")} addToCart={addToCart} onView={trackProductView}
          isFavorite={isFavorite(selectedProduct.id)} toggleFavorite={toggleFavorite} createBooking={createBooking} currentUser={currentUser} goTo={goTo} />
      )}

      {page === "favoris" && (
        <FavoritesPage currentUser={currentUser} favorites={favorites} products={products} stores={stores} goTo={goTo} toggleFavorite={toggleFavorite} addToCart={addToCart} goToProduct={(id) => { setSelectedProductId(id); goTo("product"); }} />
      )}

      {page === "checkout" && (
        <CheckoutPage
          cartItems={cartItems} subtotal={cartSubtotal} discount={discount} deliveryFee={deliveryFee} total={cartTotal}
          form={checkoutForm} setForm={setCheckoutForm} stores={stores}
          promoInput={promoInput} setPromoInput={setPromoInput} appliedPromo={appliedPromo} promoError={promoError}
          applyPromo={applyPromo} removePromo={removePromo} processing={processing} paymentError={paymentError} awaitingPayment={awaitingPayment}
          onBack={() => goTo("shop")} onSubmit={placeOrder}
        />
      )}

      {page === "orderConfirmation" && (
        <ConfirmationPage groupId={lastGroupId} orders={orders.filter((o) => o.groupId === lastGroupId)} stores={stores} onContinue={() => goTo("shop")} />
      )}

      {page === "login" && <LoginPage onSubmit={login} error={authError} goTo={goTo} />}
      {page === "register" && <RegisterPage onSubmit={register} error={authError} goTo={goTo} defaultAccountType="client" />}
      {page === "registerSeller" && <RegisterPage onSubmit={register} error={authError} goTo={goTo} defaultAccountType="vendeur" />}
      {page === "becomeSeller" && <BecomeSellerPage onSubmit={becomeSeller} currentUser={currentUser} goTo={goTo} />}

      {page === "history" && <HistoryPage currentUser={currentUser} orders={orders} stores={stores} goTo={goTo} addReview={addReview} products={products} updateOrder={updateOrder} openDispute={openDispute} disputes={disputes} />}
      {page === "profile" && <ProfilePage currentUser={currentUser} onSave={(u) => saveAll({ users: users.map((x) => (x.id === u.id ? u : x)) })} goTo={goTo} />}
      {page === "contact" && <ContactPage />}
      {page === "cgu" && <StaticLegalPage title="Conditions d'utilisation" kind="cgu" />}
      {page === "privacy" && <StaticLegalPage title="Politique de confidentialité" kind="privacy" />}

      {page === "sellerDashboard" && (
        <SellerDashboard
          currentUser={currentUser} store={currentStore}
          products={products.filter((p) => p.storeId === currentUser?.storeId)}
          orders={orders.filter((o) => o.storeId === currentUser?.storeId)}
          promoCodes={promoCodes.filter((p) => p.storeId === currentUser?.storeId)}
          allProducts={products} allPromoCodes={promoCodes} allStores={stores}
          walletTransactions={walletTransactions} withdrawals={withdrawals} referrals={referrals}
          platformSettings={platformSettings} users={users} messages={messages}
          notifications={notifications} bookings={bookings.filter((b) => b.storeId === currentUser?.storeId)}
          requestWithdrawal={requestWithdrawal} updateOrder={updateOrder} updateBooking={updateBooking} sendMessage={sendMessage}
          boostProduct={boostProduct} boostStore={boostStore} submitKyc={submitKyc}
          changePassword={changePassword} updateAccountSettings={updateAccountSettings}
          subscribeToPremium={changeSubscriptionPlan} startFreeTrial={startFreeTrial} markNotificationRead={markNotificationRead}
          callPjdAI={callPjdAI} getAiUsage={getAiUsage} getAiQuota={getAiQuota}
          saveAll={saveAll} goTo={goTo} onLogout={logout} initialTab={pendingDashboardTab}
        />
      )}
      {page === "buyerDashboard" && (
        <BuyerDashboard
          currentUser={currentUser} orders={orders.filter((o) => o.buyerId === currentUser?.id)}
          walletTransactions={walletTransactions} referrals={referrals} users={users} stores={stores}
          requestWithdrawal={requestWithdrawal} platformSettings={platformSettings}
          addReview={addReview} updateOrder={updateOrder} openDispute={openDispute} disputes={disputes.filter((d) => d.buyerId === currentUser?.id)}
          favorites={favorites} products={products} toggleFavorite={toggleFavorite} addToCart={addToCart}
          goToProduct={(id) => { setSelectedProductId(id); goTo("product"); }} bookings={bookings}
          goTo={goTo} onLogout={logout} initialTab={pendingDashboardTab}
        />
      )}
      {page === "adminDashboard" && (
        <AdminDashboard
          currentUser={currentUser} users={users} stores={stores} products={products} orders={orders}
          platformSettings={platformSettings} walletTransactions={walletTransactions} withdrawals={withdrawals}
          approveWithdrawal={approveWithdrawal} rejectWithdrawal={rejectWithdrawal} reviewKyc={reviewKyc}
          notifications={notifications} markNotificationRead={markNotificationRead} disputes={disputes} resolveDispute={resolveDispute}
          adminGrantSubscription={adminGrantSubscription} adminSuspendSubscription={adminSuspendSubscription} updateSubscriptionSettings={updateSubscriptionSettings}
          saveAll={saveAll} goTo={goTo} onLogout={logout}
        />
      )}

      {page === "myAccount" && (
        <MyAccountPage currentUser={currentUser} store={currentStore} goTo={goTo} goToSection={goToAccountSection} onLogout={logout} />
      )}

      {!isDashboard && !["login", "register", "registerSeller", "becomeSeller"].includes(page) && (
        <CartDrawer open={cartOpen} onClose={() => setCartOpen(false)} cartItems={cartItems} total={cartTotal}
          changeQty={changeQty} removeFromCart={removeFromCart}
          onCheckout={() => { setCartOpen(false); goTo("checkout"); }} />
      )}

      {!isDashboard && <Footer goTo={goTo} />}
    </div>
  );
}

/* ============================= HEADER ============================= */
